// Compare each domain with its latest row in the History tab.
// Similarweb publishes one new month at a time, so a domain gets a new row only when its month changes
// (or the first time you track it). Weeks in between add nothing.
const cfg = $('Your settings').first().json;
const sharePts = Number(cfg.alertShareChangePoints ?? 5);
const visitsPct = Number(cfg.alertVisitsChangePercent ?? 25);
const BOTS = ['chatgpt', 'gemini', 'claude', 'perplexity', 'copilot', 'deepseek', 'grok'];
const num = (v) => (v === '' || v == null || Number.isNaN(Number(v)) ? null : Number(v));
const round = (v, d = 2) => (v == null ? null : Math.round(v * 10 ** d) / 10 ** d);

// Rows are appended, so the last row for a domain is its latest.
const last = new Map();
for (const r of $input.all().map((i) => i.json)) {
  if (r.domain) last.set(String(r.domain).trim().toLowerCase(), r);
}

const today = new Date().toISOString().slice(0, 10);
const out = [];
for (const d of $('Get traffic and AI chatbot shares').all().map((i) => i.json)) {
  // No domain, or Similarweb could not be read this time: skip it, next week tries again.
  if (!d.domain || d.trafficAvailable == null) continue;
  const prev = last.get(d.domain.toLowerCase());
  if (prev && String(prev.trafficMonth ?? '') === String(d.trafficMonth ?? '')) continue;

  const shares = d.aiChatbotShares ?? {};
  const row = {
    date: today,
    domain: d.domain,
    trafficMonth: d.trafficMonth ?? '',
    monthlyVisits: d.monthlyVisits ?? '',
    aiChatbotVisits: d.aiChatbotVisits ?? '',
    aiSharePercent: d.aiChatbotShare == null ? '' : round(d.aiChatbotShare * 100, 3),
  };
  for (const b of BOTS) row[b] = shares[b] ?? '';
  const others = Object.entries(shares).filter(([k]) => !BOTS.includes(k));
  row.otherChatbots = others.length ? round(others.reduce((s, [, v]) => s + v, 0)) : '';

  // Changes against the previous row, in percentage points of AI chatbot referrals.
  const changes = [];
  if (prev) {
    for (const b of [...BOTS, 'otherChatbots']) {
      const a = num(prev[b]);
      const n = num(row[b]);
      if (a == null || n == null) continue;
      const delta = n - a;
      if (Math.abs(delta) >= sharePts) changes.push(`${b} ${delta > 0 ? '+' : ''}${round(delta, 1)} pts`);
    }
    const pv = num(prev.monthlyVisits);
    const nv = num(row.monthlyVisits);
    if (pv && nv != null) {
      const pct = ((nv - pv) / pv) * 100;
      if (Math.abs(pct) >= visitsPct) changes.push(`visits ${pct > 0 ? '+' : ''}${Math.round(pct)}%`);
    }
  }
  row.changes = prev ? (changes.join(', ') || 'no big change') : 'first row for this domain';
  row.flagged = changes.length > 0;
  row.note = d.trafficAvailable === false ? 'Similarweb has no estimate for this site' : '';
  out.push({ json: row });
}
return out;

// One Slack message for all domains that moved past your thresholds.
const rows = $input.all().map((i) => i.json).filter((r) => r.domain);
if (rows.length === 0) return [];
const pct = (v) => (v === '' || v == null ? 'n/a' : `${v}%`);
const lines = rows.map((r) =>
  `• *${r.domain}* (${r.trafficMonth}): ${r.changes}. AI chatbots sent ${pct(r.aiSharePercent)} of all visits; ` +
  `ChatGPT ${pct(r.chatgpt)}, Gemini ${pct(r.gemini)}, Claude ${pct(r.claude)}, Perplexity ${pct(r.perplexity)} of those.`);
return [{ json: {
  text: `*AI chatbot traffic: ${rows.length} domain${rows.length === 1 ? '' : 's'} changed since the last month*\n\n${lines.join('\n')}`,
} }];
